/* Undo the final mixing and the rounds numbered from start down to 0.
   The keys array must already hold the keys for those rounds. */
uint64_t peel(uint64_t c, int start, uint32_t *keys) {
    uint32_t L = getright(c), R = getleft(c);
    L ^= R;
    for (int r = start; r >= 0; r--) {
        uint32_t t = L; L = R; R = t;
        L ^= f_function(t ^ keys[r]);
    }
    R ^= L;
    return merge(L, R);
}

