    uint32_t k[4], seed[4];
    FILE *fp = fopen("pairs.txt", "r");
    for (int i = 0; i < 32; i++) if (fscanf(fp, "%lu %lu", &pt[i], &ct[i]) != 2) return 1;
    fclose(fp);

    /* The outer loop fixes all but one of the unknown keys. */
    for (uint32_t s3 = 0; s3 < (1u << 20); s3++) {
        k[3] = expand(s3);
        if (peel(ct[0], 3, k) != pt[0]) continue;
